const fs = require('fs');
const checks = {
  'tests/package-consumer/main.cpp': ['<libbsa/libbsa.hpp>', 'archive_reader', 'extract_bytes', 'contains'],
  'docs/public-api-reality-check.md': ['archive_reader', 'extract_bytes', 'COV-GAP-001', 'COV-GAP-003', 'COV-GAP-004', 'No new facade'],
  'docs/coverage-audit-matrix.md': ['COV-GAP-003', 'S05', 'package-consumer'],
  'tests/unit/docs_policy_tests.cpp': ['public-api-reality-check.md', 'extract_bytes', 'worker_count', 'BSArchPro-derived'],
  'tests/unit/target_format_policy_tests.cpp': ['COV-GAP-003', 'DirectXTex', 'Optional local'],
  'docs/api-mainpage.md': ['public-api-reality-check.md', 'coverage-audit-matrix.md'],
  'docs/integration-examples.md': ['extract_bytes', 'worker_count', 'BA2 DX10'],
  'docs/compatibility-evidence.md': ['public-api-reality-check.md', 'Optional']
};
const missing = [];
for (const [path, tokens] of Object.entries(checks)) {
  if (!fs.existsSync(path) || !fs.statSync(path).isFile()) {
    missing.push(`${path}: missing file`);
    continue;
  }
  const text = fs.readFileSync(path, 'utf8');
  const absent = tokens.filter(token => !text.includes(token));
  if (absent.length) missing.push(`${path}: missing tokens ${absent.join(', ')}`);
  else console.log(`${path}: OK`);
}
if (missing.length) {
  console.log(missing.join('\n'));
  process.exit(1);
}
console.log('S02 resume file sanity: OK');

